<script>
(()=>{const form=document.querySelector('.entrega-form'),svg=form?.querySelector('[data-entrega-svg]'),hidden=form?.elements.assinatura_recebedor,name=form?.elements.recebedor_nome,submit=form?.querySelector('[data-entrega-submit]');if(!form||!svg||!hidden||!name||!submit)return;const serializar=()=>{const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width','900');clone.setAttribute('height','270');const bytes=new TextEncoder().encode(new XMLSerializer().serializeToString(clone));let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return`data:image/svg+xml;base64,${btoa(binary)}`};const atualizar=()=>{const assinou=Boolean(svg.querySelector('path'));hidden.value=assinou?serializar():'';submit.disabled=!(name.value.trim()&&assinou)};name.addEventListener('input',atualizar);new MutationObserver(atualizar).observe(svg,{childList:true,subtree:true,attributes:true,attributeFilter:['d']});atualizar();document.addEventListener('submit',async event=>{if(event.target!==form)return;event.preventDefault();event.stopImmediatePropagation();atualizar();if(submit.disabled){window.showAppToast?.('Informe o recebedor e faça a assinatura.','error');return}if(form.dataset.confirming==='1')return;form.dataset.confirming='1';submit.disabled=true;try{const response=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível confirmar a entrega.');if(data.confirmado!==true||data.assinatura_salva!==true||data.status!=='entregue'||!data.recebedor_nome||!data.data_recebimento)throw new Error('O servidor não confirmou todos os dados da entrega.');window.showAppToast?.('Assinatura salva com sucesso.','success');setTimeout(()=>location.assign(`${location.pathname}?tab=concluidos`),350)}catch(error){window.showAppToast?.(error.message||'Não foi possível confirmar a entrega. Tente novamente.','error');atualizar()}finally{delete form.dataset.confirming;atualizar()}},true)})();
</script>
